        {
          "stage": "benefit",
          "focus": "把手端拿",
          "sentences": [
            {
              "display_text": "杯子带一个把手，端起来的时候手指有地方放，不用整只手去圈杯身。",
              "spoken_text": "杯子带一个把手，端起来的时候手指有地方放，不用整只手去圈杯身。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
